"""Incident status state machine and immutable transition history.

An incident moves ``open -> acknowledged -> resolved`` only. Every accepted
transition updates the incident row and appends one immutable history record
inside a single locked write transaction, so the new status and its history
entry are committed together or not at all, and concurrent transitions cannot
both observe the same prior status. Rejected transitions write nothing. The
history record is appended to the machine's tamper-evident status-event hash
chain in the same transaction, so the status, the record, and its chain link
commit together or leave no trace.
"""

from typing import Any

from sqlalchemy import Connection, Engine, select
from sqlalchemy.orm import Session

from . import status_event_chain
from .chain import _run_with_lock_retry
from .db import (
    AuthorizationDecisionEvent,
    AuthorizationDecisionIncident,
    IncidentStatusEvent,
    Machine,
)

_INCIDENT_TABLE = AuthorizationDecisionIncident.__table__

# The only legal edges of the incident state machine.
_ALLOWED_TRANSITIONS = {
    "open": "acknowledged",
    "acknowledged": "resolved",
}


def get_machine_event_incident(
    session: Session, machine_id: str, event_id: str, incident_id: str
) -> AuthorizationDecisionIncident | None:
    """Resolve an incident that belongs to the path machine and event.

    Returns ``None`` when the machine, event, or incident is missing or when
    any of them belongs to a different owner than the path claims.
    """
    machine = session.get(Machine, machine_id)
    if machine is None:
        return None
    event = session.scalar(
        select(AuthorizationDecisionEvent).where(
            AuthorizationDecisionEvent.id == event_id,
            AuthorizationDecisionEvent.machine_id == machine_id,
        )
    )
    if event is None:
        return None
    return session.scalar(
        select(AuthorizationDecisionIncident).where(
            AuthorizationDecisionIncident.id == incident_id,
            AuthorizationDecisionIncident.machine_id == machine_id,
            AuthorizationDecisionIncident.event_id == event_id,
        )
    )


def change_incident_status(
    engine: Engine,
    *,
    machine_id: str,
    event_id: str,
    incident_id: str,
    to_status: str,
) -> dict[str, Any]:
    """Atomically advance one incident's status and append its history record.

    All lookups and the write happen in one locked transaction. Returns a
    status dict:

    * ``not_found`` — the machine, event, or incident is missing or owned by
      another machine/event;
    * ``invalid_status_transition`` — the incident's current status has no edge
      to ``to_status`` (nothing is written);
    * ``ok`` — with the updated ``incident`` and the new ``history`` record.
    """

    def _work(conn: Connection) -> dict[str, Any]:
        machine = conn.execute(
            Machine.__table__.select().where(Machine.__table__.c.id == machine_id)
        ).first()
        if machine is None:
            return {"status": "not_found"}
        event = conn.execute(
            AuthorizationDecisionEvent.__table__.select().where(
                AuthorizationDecisionEvent.__table__.c.id == event_id,
                AuthorizationDecisionEvent.__table__.c.machine_id == machine_id,
            )
        ).first()
        if event is None:
            return {"status": "not_found"}
        incident_row = conn.execute(
            _INCIDENT_TABLE.select().where(
                _INCIDENT_TABLE.c.id == incident_id,
                _INCIDENT_TABLE.c.machine_id == machine_id,
                _INCIDENT_TABLE.c.event_id == event_id,
            )
        ).first()
        if incident_row is None:
            return {"status": "not_found"}

        incident = incident_row._mapping
        from_status = incident["status"]
        if _ALLOWED_TRANSITIONS.get(from_status) != to_status:
            return {"status": "invalid_status_transition"}

        conn.execute(
            _INCIDENT_TABLE.update()
            .where(_INCIDENT_TABLE.c.id == incident_id)
            .values(status=to_status)
        )
        # Append the history record to the machine's status-event chain tail
        # inside the same locked transaction: the incident status, the record,
        # and its chain link commit together or not at all.
        history = status_event_chain.mint_tail_link(
            conn,
            machine_id=machine_id,
            event_id=event_id,
            incident_id=incident_id,
            from_status=from_status,
            to_status=to_status,
        )
        return {
            "status": "ok",
            "incident": {
                "id": incident["id"],
                "machine_id": incident["machine_id"],
                "event_id": incident["event_id"],
                "incident_type": incident["incident_type"],
                "summary": incident["summary"],
                "status": to_status,
                "created_at": incident["created_at"],
            },
            "history": history,
        }

    return _run_with_lock_retry(engine, _work)


def list_status_history(
    session: Session, machine_id: str, event_id: str, incident_id: str
) -> list[IncidentStatusEvent]:
    """Return one incident's immutable transitions in (created_at, id) order."""
    return list(
        session.scalars(
            select(IncidentStatusEvent)
            .where(
                IncidentStatusEvent.machine_id == machine_id,
                IncidentStatusEvent.event_id == event_id,
                IncidentStatusEvent.incident_id == incident_id,
            )
            .order_by(IncidentStatusEvent.created_at, IncidentStatusEvent.id)
        )
    )

def get_machine_event(
    session: Session, machine_id: str, event_id: str
) -> AuthorizationDecisionEvent | None:
    return session.scalar(
        select(AuthorizationDecisionEvent).where(
            AuthorizationDecisionEvent.id == event_id,
            AuthorizationDecisionEvent.machine_id == machine_id,
        )
    )


def introduces_cycle(
    session: Session, machine_id: str, cause_event_id: str, effect_event_id: str
) -> bool:
    """Whether a new cause -> effect edge would close a directed cycle.

    Follows existing cause -> effect edges from the proposed effect; reaching
    the proposed cause means the new edge closes a loop.
    """
    links = session.scalars(
        select(AuthorizationDecisionCausalLink).where(
            AuthorizationDecisionCausalLink.machine_id == machine_id
        )
    ).all()
    adjacency: dict[str, list[str]] = {}
    for link in links:
        adjacency.setdefault(link.cause_event_id, []).append(link.effect_event_id)

    visited = {effect_event_id}
    stack = [effect_event_id]
    while stack:
        current = stack.pop()
        if current == cause_event_id:
            return True
        for nxt in adjacency.get(current, []):
            if nxt not in visited:
                visited.add(nxt)
                stack.append(nxt)
    return False


@app.post(
    "/machines/{machine_id}/authorization-decision-events/{cause_event_id}/causal-links",
    status_code=201,
    response_model=CausalLinkOut,
)
def create_causal_link(
    machine_id: str,
    cause_event_id: str,
    body: CausalLinkCreate,
    session: SessionDep,
):
    cause_event = get_machine_event(session, machine_id, cause_event_id)
    effect_event = get_machine_event(session, machine_id, body.effect_event_id)
    if cause_event is None or effect_event is None:
        return error_response(404, "not_found")
    if cause_event_id == body.effect_event_id:
        return error_response(422, "self_causal_link")

    existing = session.scalar(
        select(AuthorizationDecisionCausalLink).where(
            AuthorizationDecisionCausalLink.machine_id == machine_id,
            AuthorizationDecisionCausalLink.cause_event_id == cause_event_id,
            AuthorizationDecisionCausalLink.effect_event_id == body.effect_event_id,
        )
    )
    if existing is not None:
        return error_response(409, "duplicate_causal_link")
    if introduces_cycle(session, machine_id, cause_event_id, body.effect_event_id):
        return error_response(409, "causal_cycle")

    link = AuthorizationDecisionCausalLink(
        id=str(uuid.uuid4()),
        machine_id=machine_id,
        cause_event_id=cause_event_id,
        effect_event_id=body.effect_event_id,
        created_at=utc_now_iso(),
    )
    session.add(link)
    try:
        session.commit()
    except IntegrityError:
        session.rollback()
        return error_response(409, "duplicate_causal_link")
    return causal_link_to_out(link)


@app.get(
    "/machines/{machine_id}/authorization-decision-events/{cause_event_id}/causal-links",
    response_model=list[CausalLinkOut],
)
def list_causal_links(machine_id: str, cause_event_id: str, session: SessionDep):
    cause_event = get_machine_event(session, machine_id, cause_event_id)
    if cause_event is None:
        return error_response(404, "not_found")

    links = session.scalars(
        select(AuthorizationDecisionCausalLink)
        .where(
            AuthorizationDecisionCausalLink.machine_id == machine_id,
            AuthorizationDecisionCausalLink.cause_event_id == cause_event_id,
        )
        .order_by(
            AuthorizationDecisionCausalLink.created_at,
            AuthorizationDecisionCausalLink.id,
        )
    ).all()
    return [causal_link_to_out(link) for link in links]


